ng:16px 20px;border-top:1px solid var(--line);color:var(--muted)}.pages{display:flex;gap:8px}.pages button{padding:7px 11px;background:#eef2f7;color:#344255}.pages button:disabled{opacity:.45;cursor:default}@media(max-width:640px){.shell{padding:24px 14px}.top,.toolbar,.pagination{align-items:stretch;flex-direction:column}.search{width:100%}h1{font-size:26px}}
