    <div class="toolbar"><div class="count" id="count">Loading records…</div><form class="search" id="searchForm" role="search"><input id="searchInput" type="search" placeholder="Search event, user, IP…" aria-label="Search security logs"><button>Search</button><button type="button" class="clear" id="clearButton" hidden>Clear</button></form></div>
