<script>
const endpoint='security_logs_api.php';let currentPage=1;let currentQuery='';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function resultFor(event,description){const text=(event+' '+description).toLowerCase();if(/fail|denied|blocked|unauthori[sz]ed|invalid|error/.test(text))return['Failed','failed'];if(/success|successful|created|registered|registration|updated|deleted|logout|uploaded|changed/.test(text))return['Success','success'];return['Recorded','recorded'];}
async function loadLogs(){const results=document.getElementById('results');results.className='empty';results.textContent='Loading security logs…';try{const url=new URL(endpoint,location.href);url.searchParams.set('page',currentPage);if(currentQuery)url.searchParams.set('q',currentQuery);const response=await fetch(url);if(!response.ok)throw new Error('Could not load security logs.');const data=await response.json();document.getElementById('count').textContent=`Showing ${data.total?((data.page-1)*25+1):0}–${Math.min(data.page*25,data.total)} of ${data.total} records`;document.getElementById('clearButton').hidden=!currentQuery;if(!data.logs.length){results.textContent=currentQuery?'No security logs found for this search.':'No security logs found.';document.getElementById('pagination').hidden=true;return;}results.className='table-wrap';results.innerHTML=`<table><thead><tr><th>Time</th><th>Event</th><th>User / Admin</th><th>IP address</th><th>Result</th></tr></thead><tbody>${data.logs.map(log=>{const isUser=log.user_id!==null;const hasAdmin=log.admin_id!==null;const name=isUser?(log.user_name||'Deleted user'):(hasAdmin?(log.admin_name||'Deleted administrator'):'System');const email=isUser?log.user_email:(hasAdmin?log.admin_email:'System event');const [label,kind]=resultFor(log.event_type,log.description||'');const time=new Date(String(log.created_at).replace(' ','T')).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});return `<tr><td class="time">${esc(time)}</td><td><div class="event">${esc(log.event_type)}</div>${log.description?`<div class="desc">${esc(log.description)}</div>`:''}</td><td class="account"><strong>${esc(name)}</strong><span>${esc(email||(isUser?'User':'Administrator'))}</span></td><td class="ip">${esc(log.ip_address||'—')}</td><td><span class="badge ${kind}">${label}</span></td></tr>`}).join('')}</tbody></table>`;document.getElementById('pagination').hidden=data.pages<=1;document.getElementById('pageLabel').textContent=`Page ${data.page} of ${data.pages}`;document.getElementById('previous').disabled=data.page<=1;document.getElementById('next').disabled=data.page>=data.pages;}catch(error){results.className='empty';results.textContent=error.message;document.getElementById('pagination').hidden=true;}}
document.getElementById('searchForm').addEventListener('submit',event=>{event.preventDefault();currentQuery=document.getElementById('searchInput').value.trim();currentPage=1;loadLogs();});document.getElementById('clearButton').addEventListener('click',()=>{document.getElementById('searchInput').value='';currentQuery='';currentPage=1;loadLogs();});document.getElementById('previous').addEventListener('click',()=>{if(currentPage>1){currentPage--;loadLogs();}});document.getElementById('next').addEventListener('click',()=>{currentPage++;loadLogs();});loadLogs();
</script>  <script src="admin_logout.js"></script>
